// SHADI SALOON app intro/splash overlay -- shown once at the start of
// opening the app, before the real UI paints. Self-contained (styles +
// images inlined, scoped under #shadiAppIntro) so it can be dropped into
// any page with one script tag; no dependency on the host app's own CSS
// or JS. Content/timing is the hand-off file as authored, unmodified --
// only wrapped in a full-viewport overlay and namespaced so its plain
// class names (.stage, .piece, .letter, .sheen...) can never collide with
// the host page's own CSS.
//
// Usage: set window.__shadiIntroReadyElId to the id of the element that
// marks "the real app has painted" (defaults to "app") before this script
// runs, if the host page uses something other than <div id="app">.
(function () {
  if (window.__shadiIntroShown) return;
  window.__shadiIntroShown = true;

  var overlay = document.createElement('div');
  overlay.id = 'shadiAppIntro';
  overlay.innerHTML = "<style>\n  #shadiAppIntro{position:fixed;inset:0;z-index:999999;background:#ffffff;display:flex;align-items:center;justify-content:center;overflow:hidden;}\n  #shadiAppIntro .stage{\n    position:relative;\n    width:100%; max-width:520px;\n    display:flex; flex-direction:column; align-items:center; justify-content:center;\n  }\n  #shadiAppIntro .icon-wrap{\n    position:relative;\n    width:42%;\n    aspect-ratio:354/430;\n    filter:drop-shadow(0 0 0 rgba(0,0,0,0));\n    animation:glow 0.9s ease-out forwards;\n    animation-delay:1.58s;\n  }\n  #shadiAppIntro .piece{\n    position:absolute; left:0; width:100%;\n    opacity:0;\n    object-fit:contain;\n  }\n  #shadiAppIntro .p-bristles{ transform:translateY(-16px); animation:pieceInDown 0.6s cubic-bezier(.2,.8,.2,1) forwards; }\n  #shadiAppIntro .p-handle{ transform:scale(0.7); animation:pieceInScale 0.5s ease-out forwards; }\n  #shadiAppIntro .p-mustache{ transform:translateX(0) scale(0.85); animation:pieceInScale 0.55s cubic-bezier(.2,.8,.2,1) forwards; }\n  #shadiAppIntro .p-base{ transform:translateY(14px); animation:pieceInUp 0.5s ease-out forwards; }\n\n  @keyframes pieceInDown{ to{ opacity:1; transform:translateY(0); } }\n  @keyframes pieceInUp{ to{ opacity:1; transform:translateY(0); } }\n  @keyframes pieceInScale{ to{ opacity:1; transform:scale(1); } }\n\n  @keyframes glow{\n    0%{ filter:drop-shadow(0 0 0 rgba(0,0,0,0)); }\n    45%{ filter:drop-shadow(0 0 14px rgba(0,0,0,0.18)); }\n    100%{ filter:drop-shadow(0 0 0 rgba(0,0,0,0)); }\n  }\n\n  #shadiAppIntro .word-wrap{\n    position:relative;\n    width:72%;\n    aspect-ratio:652/63;\n    margin-top:6%;\n  }\n  #shadiAppIntro .letter{\n    position:absolute; top:0; height:100%;\n    opacity:0;\n    transform:translateY(16px);\n    animation:letterIn 0.45s cubic-bezier(.2,.8,.2,1) forwards;\n  }\n  @keyframes letterIn{ to{ opacity:1; transform:translateY(0); } }\n\n  #shadiAppIntro .sheen{\n    position:absolute; top:0; left:-30%;\n    width:25%; height:100%;\n    background:linear-gradient(100deg, transparent, rgba(0,0,0,0.10), transparent);\n    transform:skewX(-15deg);\n    opacity:0;\n    animation:sweep 1.1s ease-in-out forwards;\n    animation-delay:2.80s;\n    pointer-events:none;\n  }\n  @keyframes sweep{\n    0%{ opacity:0; left:-30%; }\n    15%{ opacity:1; }\n    70%{ opacity:1; }\n    100%{ opacity:0; left:110%; }\n  }\n</style><div class=\"stage\">\n  <div class=\"icon-wrap\">\n    <img class=\"piece p-bristles\" src=\"data:image/png;base64,\" style=\"top:0.000%; height:44.651%; animation-delay:0.10s;\">\n<img class=\"piece p-handle\" src=\"data:image/png;base64,\" style=\"top:44.651%; height:12.558%; animation-delay:0.43s;\">\n<img class=\"piece p-mustache\" src=\"data:image/png;base64,\" style=\"top:57.209%; height:22.791%; animation-delay:0.71s;\">\n<img class=\"piece p-base\" src=\"data:image/png;base64,\" style=\"top:80.000%; height:20.000%; animation-delay:1.01s;\">\n\n  </div>\n  <div class=\"word-wrap\">\n    <img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:0.000%; width:8.282%; animation-delay:1.53s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:8.436%; width:9.356%; animation-delay:1.60s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:17.638%; width:10.583%; animation-delay:1.67s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:28.067%; width:9.663%; animation-delay:1.74s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:38.037%; width:3.067%; animation-delay:1.81s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:44.785%; width:8.589%; animation-delay:1.88s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:52.607%; width:10.583%; animation-delay:1.95s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:63.037%; width:7.055%; animation-delay:2.02s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:69.479%; width:10.736%; animation-delay:2.09s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:80.061%; width:10.736%; animation-delay:2.16s;\">\n<img class=\"letter\" src=\"data:image/png;base64,\" style=\"left:91.104%; width:8.896%; animation-delay:2.23s;\">\n\n  </div>\n  <div class=\"sheen\"></div>\n</div>";
  document.body.insertBefore(overlay, document.body.firstChild);

  // Full choreographed runtime per the file's own timing: last letter
  // finishes at 2.23s + 0.45s = 2.68s, the sheen sweep runs 2.80s-3.90s.
  // Never dismiss before that finishes playing, no matter how fast the
  // real app underneath is ready.
  var MIN_MS = 4100;
  // Hard cap so a real app that's unusually slow to paint (or a
  // misconfigured readyElId) can never leave this stuck on screen forever.
  var MAX_MS = 8000;
  var readyElId = window.__shadiIntroReadyElId || 'app';
  var startedAt = Date.now();

  function dismiss() {
    overlay.style.transition = 'opacity .4s ease';
    overlay.style.opacity = '0';
    setTimeout(function () { overlay.remove(); }, 420);
  }
  function poll() {
    var elapsed = Date.now() - startedAt;
    var readyEl = document.getElementById(readyElId);
    var appReady = !!(readyEl && readyEl.children && readyEl.children.length > 0);
    if ((elapsed >= MIN_MS && appReady) || elapsed >= MAX_MS) {
      dismiss();
    } else {
      setTimeout(poll, 100);
    }
  }
  setTimeout(poll, MIN_MS);
})();
